SELECT (SELECT count(*) FROM pragma_table_info('a')) AS a_columns,(SELECT count(*) FROM pragma_table_info('b')) AS b_columns,(SELECT group_concat(name,',') FROM (SELECT name FROM pragma_index_list('a') ORDER BY name)) AS a_indexes,(SELECT group_concat(name,',') FROM (SELECT name FROM pragma_index_info('a1') ORDER BY seqno)) AS a1_columns,(SELECT group_concat(name,',') FROM (SELECT name FROM pragma_index_info('a2') ORDER BY seqno)) AS a2_columns,(SELECT group_concat(name,',') FROM (SELECT name FROM pragma_index_info('b1') ORDER BY seqno)) AS b1_columns